using Dhole.Content.Domain.ContentItems.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace Dhole.Content.Persistence.Configurations.ContentItems;internal sealed class ContentRevisionConfiguration:IEntityTypeConfiguration<ContentRevision>{public void Configure(EntityTypeBuilder<ContentRevision>b){b.ToTable("content_revisions");b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.Title).HasMaxLength(300).IsRequired();b.Property(x=>x.Slug).HasMaxLength(300).IsRequired();b.Property(x=>x.Excerpt).HasMaxLength(1200);b.Property(x=>x.BlocksJson).HasColumnType("jsonb").IsRequired();b.Property(x=>x.RenderedHtml).HasColumnType("text");b.Property(x=>x.StructuredDataJson).HasColumnType("jsonb");b.Property(x=>x.Reason).HasMaxLength(300);b.HasIndex(x=>new{x.ContentId,x.RevisionNumber}).IsUnique();}}
